#!/usr/bin/env python3
"""Build the self-contained offline spinner page and vocabulary download."""

from html import escape
import json
import os
from pathlib import Path
import sys
import tempfile
from typing import Tuple


ROOT = Path(__file__).resolve().parents[1]
ASSET_DIR = Path('extras') / 'spinner'
TXT_NAME = 'spinner-verbs-2.1.322.txt'
GENERATED_MARKER = (
    '<!-- GENERATED by scripts/build_spinner.py from verbs.json, spinner.css, '
    'spinner.js, template.html and LICENSE. Do not edit. -->'
)


def _read_words(root: Path) -> list:
    words = json.loads((root / ASSET_DIR / 'verbs.json').read_text(encoding='utf-8'))
    if not isinstance(words, list) or not all(isinstance(word, str) and word for word in words):
        raise ValueError('spinner verbs must be a JSON array of non-empty strings')
    if len(words) != 187:
        raise ValueError(f'spinner vocabulary must contain 187 words, found {len(words)}')
    if len(set(words)) != len(words):
        raise ValueError('spinner vocabulary must not contain duplicates')
    return words


def load_spinner_assets(root: Path) -> dict[str, str]:
    """Load canonical CSS/JS plus JSON safe for an inline script element."""
    root = Path(root)
    words = _read_words(root)
    data_json = json.dumps(words, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    return {
        'css': (root / ASSET_DIR / 'spinner.css').read_text(encoding='utf-8'),
        'js': (root / ASSET_DIR / 'spinner.js').read_text(encoding='utf-8'),
        'data_json': data_json,
    }


def render_spinner(root: Path) -> Tuple[str, str]:
    """Return generated HTML and TXT without touching tracked files."""
    root = Path(root)
    assets = load_spinner_assets(root)
    words = json.loads(assets['data_json'])
    template = (root / ASSET_DIR / 'template.html').read_text(encoding='utf-8')
    replacements = {
        '<!-- CC_SPINNER_STYLE -->': '<style>\n' + assets['css'] + '</style>',
        '<!-- CC_SPINNER_WORDS -->':
            '\n'.join('        <li>' + escape(word) + '</li>' for word in words),
        '<!-- CC_SPINNER_DATA -->':
            '<script type="application/json" id="cc-spinner-data">' + assets['data_json'] + '</script>',
        '<!-- CC_SPINNER_SCRIPT -->': '<script>\n' + assets['js'] + '</script>',
        '<!-- CC_SPINNER_LICENSE -->': escape((root / 'LICENSE').read_text(encoding='utf-8')),
    }
    for marker, replacement in replacements.items():
        if template.count(marker) != 1:
            raise ValueError(f'expected exactly one template marker: {marker}')
        template = template.replace(marker, replacement)
    if template.count('</head>') != 1 or template.count('</body>') != 1:
        raise ValueError('spinner template must contain one head and body close')
    html = template.replace(
        '<!doctype html>\n', '<!doctype html>\n' + GENERATED_MARKER + '\n', 1
    )
    return html, '\n'.join(words) + '\n'


def _atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix='.' + path.name + '.', dir=path.parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='\n') as handle:
            handle.write(content)
        os.replace(temporary, path)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise


def build(root: Path = ROOT) -> Tuple[Path, Path]:
    """Generate and atomically replace both tracked share artifacts."""
    html, txt = render_spinner(root)
    output = Path(root) / ASSET_DIR
    index = output / 'index.html'
    vocabulary = output / TXT_NAME
    _atomic_write(index, html)
    _atomic_write(vocabulary, txt)
    return index, vocabulary


def main() -> int:
    try:
        index, vocabulary = build(ROOT)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print(f'build_spinner.py: {exc}', file=sys.stderr)
        return 2
    print(f'wrote {index.relative_to(ROOT)}')
    print(f'wrote {vocabulary.relative_to(ROOT)}')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
